class Boeing {
}

class Airline {
  + Name : string
}

class Employee {
  + Name : string
}

class Salesperson {
}

class Contract {
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + Model : string
  + Price : float
  + Options : string
  + DeliveryDate : date
}

class Airplane {
  + SerialNumber : string
}

Salesperson --|> Employee
Salesperson "1" -- "0..*" Contract : manages
Contract "1" -- "1..*" Acquisition : consistsOf
Acquisition "1" -- "1" Airplane : for
Airline "1" -- "0..*" Contract : signs
Airline "0..1" o-- "0..*" Airline : daughterOf
Airline "0..1" o-- "0..*" Airline : motherOf
Boeing "1" -- "0..*" Contract : sellsTo
@enduml

